#include "Studio.h"
namespace pulse {
using namespace juce;
GroovePreset Studio::captureGroovePreset(const String& id,const String& name)const{return {id,name,grooveSettings};}
bool Studio::applyGroovePreset(const GroovePreset& p,uint64_t expected,uint64_t serial){if(!grooveContext(expected,serial)){status="Groove source or settings changed. Reopen Presets.";return false;}auto valid=validateGroovePreset(p);if(valid.failed()){status=valid.getErrorMessage();return false;}grooveSettings=p.settings;selectedGroove=p.id;grooveName=p.name;++grooveSerial;refreshNoteToolPreview();status="Loaded "+p.name+(noteToolValid?". Preview only; Apply changes notes.":". Resolve the boundary/settings error before Apply.");repaint();return true;}
bool Studio::storeGroovePreset(const GroovePreset& p,bool replace,const String& token){if(recording||recorder.isActive()){status="Finish the take before saving grooves.";return false;}auto valid=putGroovePreset(root.getChildFile("data/groove-presets.json"),p,replace,token);if(valid.failed()){status=valid.getErrorMessage();return false;}selectedGroove=p.id;grooveName=p.name;status="Saved local groove: "+p.name+". Apply commits note changes.";repaint();return true;}
bool Studio::deleteGroovePreset(const String& id,const String& token){if(recording||recorder.isActive()){status="Finish the take before deleting grooves.";return false;}auto valid=removeGroovePreset(root.getChildFile("data/groove-presets.json"),id,token);if(valid.failed()){status=valid.getErrorMessage();return false;}if(selectedGroove==id)selectedGroove.clear();status="Groove preset deleted. Current preview retained.";repaint();return true;}
void Studio::nameGroovePreset(GroovePreset p,bool rename,const String& token){auto* dialog=new AlertWindow(rename?"Rename groove preset":"Save groove preset","Save groove settings only, without source notes, sample paths or capture range. Use a unique name of 1-64 characters.",MessageBoxIconType::NoIcon,this);dialog->addTextEditor("name",p.name);dialog->addButton(rename?"Rename":"Save",1,KeyPress(KeyPress::returnKey));dialog->addButton("Cancel",0,KeyPress(KeyPress::escapeKey));auto safe=Component::SafePointer<Studio>(this);auto expected=revision,serial=grooveSerial;dialog->enterModalState(true,ModalCallbackFunction::create([safe,dialog,p,rename,token,expected,serial](int choice)mutable{if(!safe||choice!=1)return;if(!safe->grooveContext(expected,serial)){safe->status="Groove source or settings changed. Reopen Save preset.";return;}p.name=dialog->getTextEditorContents("name").trim();safe->storeGroovePreset(p,rename,token);}),true);}
void Studio::showGroovePresets(){
    if(!grooveContext(revision,grooveSerial)){status="Start a current groove preview before choosing presets.";return;}auto file=root.getChildFile("data/groove-presets.json");auto token=groovePresetToken(file);std::vector<GroovePreset> personal;auto loaded=loadGroovePresets(file,personal);if(loaded.failed())status=loaded.getErrorMessage();std::sort(personal.begin(),personal.end(),[](const auto& a,const auto& b){return a.name.compareIgnoreCase(b.name)<0;});auto factories=factoryGroovePresets();auto found=std::find_if(personal.begin(),personal.end(),[&](const auto& p){return p.id==selectedGroove;});bool selected=found!=personal.end();auto current=selected?*found:captureGroovePreset(Uuid().toString(),"Groove settings");
    PopupMenu menu,factoryMenu,personalMenu;menu.addSectionHeader("Timing and velocity grooves");for(int i=0;i<(int)factories.size();++i)factoryMenu.addItem(100+i,factories[(size_t)i].name,true,selectedGroove==factories[(size_t)i].id);menu.addSubMenu("Factory",factoryMenu);if(personal.empty())personalMenu.addItem(999,"No personal grooves yet",false);else for(int start=0;start<(int)personal.size();start+=24){PopupMenu page;for(int i=start;i<jmin(start+24,(int)personal.size());++i)page.addItem(1000+i,personal[(size_t)i].name,true,selectedGroove==personal[(size_t)i].id);if(personal.size()<=24)personalMenu=page;else personalMenu.addSubMenu(String(start+1)+" - "+String(jmin(start+24,(int)personal.size())),page);}menu.addSubMenu("Personal",personalMenu);
    menu.addSeparator();menu.addItem(8,"Capture from original source notes...");menu.addItem(1,"Save settings as new groove...",loaded.wasOk()&&personal.size()<maxGroovePresets);menu.addItem(2,"Update selected personal groove",loaded.wasOk()&&selected);menu.addItem(3,"Rename selected personal groove...",loaded.wasOk()&&selected);menu.addItem(4,"Delete selected personal groove...",loaded.wasOk()&&selected);menu.addSeparator();menu.addItem(5,"Import one groove...",loaded.wasOk()&&personal.size()<maxGroovePresets);menu.addItem(6,"Export current groove settings...");if(loaded.failed())menu.addItem(7,"Personal library unavailable - see status",false);auto safe=Component::SafePointer<Studio>(this);auto expected=revision,serial=grooveSerial;
    menu.showMenuAsync(menuOptions(notePresetsOpen),[safe,factories,personal,current,selected,token,expected,serial](int result){
        if(!safe||!result)return;if(!safe->grooveContext(expected,serial)){safe->status="Groove source or settings changed. Reopen Presets.";return;}if(result>=100&&result<100+(int)factories.size()){safe->applyGroovePreset(factories[(size_t)(result-100)],expected,serial);return;}if(result==8){safe->showGrooveCapture();return;}auto library=safe->root.getChildFile("data/groove-presets.json");if(result!=6&&groovePresetToken(library)!=token){safe->status="Groove library changed. Reopen Presets.";return;}if(result>=1000&&result<1000+(int)personal.size()){safe->applyGroovePreset(personal[(size_t)(result-1000)],expected,serial);return;}
        if(result==1){safe->nameGroovePreset(safe->captureGroovePreset(Uuid().toString(),""),false,token);return;}if(result==2&&selected){safe->storeGroovePreset(safe->captureGroovePreset(current.id,current.name),true,token);return;}if(result==3&&selected){safe->nameGroovePreset(current,true,token);return;}
        if(result==4&&selected){auto* dialog=new AlertWindow("Delete groove preset","Delete \""+current.name+"\" from this local library? Current preview settings are retained.",MessageBoxIconType::QuestionIcon,safe.getComponent());dialog->addButton("Delete",1);dialog->addButton("Cancel",0,KeyPress(KeyPress::escapeKey));dialog->enterModalState(true,ModalCallbackFunction::create([safe,current,token,expected,serial](int choice){if(!safe||choice!=1)return;if(!safe->grooveContext(expected,serial)){safe->status="Groove context changed. Reopen Delete preset.";return;}safe->deleteGroovePreset(current.id,token);}),true);return;}
        if(result==5||result==6){bool exporting=result==6;auto captured=safe->captureGroovePreset(Uuid().toString(),selected?current.name:"Groove settings");if(exporting){auto valid=validateGroovePreset(captured);if(valid.failed()){safe->status=valid.getErrorMessage();return;}}safe->chooser=std::make_unique<FileChooser>(exporting?"Export groove settings":"Import one groove preset",exporting?safe->root.getChildFile("groove.pulsegroove"):safe->root,"*.pulsegroove",true);int flags=exporting?FileBrowserComponent::saveMode|FileBrowserComponent::canSelectFiles|FileBrowserComponent::warnAboutOverwriting:FileBrowserComponent::openMode|FileBrowserComponent::canSelectFiles;
            safe->chooser->launchAsync(flags,[safe,exporting,captured,token,expected,serial](const FileChooser& chooser){if(!safe)return;auto file=chooser.getResult();if(file==File())return;if(!safe->grooveContext(expected,serial)){safe->status="Groove context changed. Reopen preset exchange.";return;}if(exporting){auto valid=saveGroovePresets(file,{captured},groovePresetToken(file));safe->status=valid.wasOk()?"Groove exported: "+file.getFileName():valid.getErrorMessage();return;}std::vector<GroovePreset> rows;auto valid=loadGroovePresets(file,rows);if(valid.failed()||rows.size()!=1){safe->status=valid.failed()?valid.getErrorMessage():"Choose one exported groove preset.";return;}auto p=rows.front();p.id=Uuid().toString();safe->nameGroovePreset(p,false,token);});}
    });
}
}
